package bom

type RuleDefinition struct {
	ID       string `json:"rule_id"`
	Version  string `json:"version"`
	Scope    string `json:"scope"`
	Severity string `json:"severity"`
	Basis    string `json:"basis"`
	Remedy   string `json:"remediation"`
}

func RuleCatalog() []RuleDefinition {
	rules := []RuleDefinition{}
	for _, r := range []struct{ ID, Scope, Basis, Remedy string }{{"PROFILE-CONFIRM", "workbook", "Every nonempty region has an explicit human disposition", "Confirm Sheet purpose, fields and data boundaries"}, {"MAPPING-REVIEW", "import", "Candidates cannot be official facts without review", "Confirm candidate revision"}, {"BOM-SERIAL", "material", "Serial-bearing identities require serial", "Map existing source or retain blocker; never fabricate"}, {"BOM-MODEL", "material", "Material model must be explicit", "Map the source model"}, {"MODEL-APPROVED-REVISION", "model", "Model resolves uniquely to approved revision", "Select/approve exact model with evidence"}, {"SOURCE-ROW-COVERAGE", "source-region", "Mapped source rows cannot silently disappear", "Restore record or explicitly exclude source row with reason"}, {"BOM-CANDIDATE-ID", "candidate", "Unique review-scope identity", "Keep candidate identity stable and distinct"}, {"BOM-IDENTITY", "material", "Unique material identity", "Reconcile conflicting cross-Sheet records"}, {"BOM-PARENT-CYCLE", "component", "Acyclic containment graph", "Correct parent references"}, {"BOM-PARENT", "component", "Valid distinct stable parent", "Confirm parent reference"}, {"BOM-CABLE", "connection", "Both ends reference physical ports", "Confirm endpoint candidates"}, {"BOM-PORT-OCCUPIED", "connection", "Single physical connection per port", "Correct duplicate or conflicting cabling"}, {"ENDPOINT-SOURCE-CONFLICT", "connection", "Selected port matches explicit mapped endpoint", "Correct normalized value with reason or select correct port"}, {"CABLE-SPEED-EVIDENCE", "connection", "Both endpoint speed units known", "Map units from source; unknown stays blocked"}, {"CABLE-SPEED-MISMATCH", "connection", "Approved endpoint speed compatibility", "Correct planning or provide approved capability"}, {"CABLE-MEDIA", "connection", "Explicit physical medium", "Map cable medium"}, {"MODEL-BREAKOUT", "port", "Approved model capability", "Bind approved breakout variant"}, {"OPTIC-PORT", "optic", "Optic has physical port owner", "Confirm port association"}, {"OPTIC-SPEED", "optic", "Compatible explicit port/optic rates", "Resolve mismatch"}, {"OPTIC-TYPE", "optic", "Explicit compatible optic and port types", "Map compatible type evidence"}, {"BOM-U-CONFLICT", "rack", "No overlapping occupied U ranges", "Correct confirmed rack placement"}, {"BOM-U-RANGE", "rack", "Known rack capacity and device height", "Bind confirmed dimensions"}, {"BOM-IP", "field", "IP parses as IPv4/IPv6", "Correct normalized IP"}, {"BOM-MAC", "field", "MAC parses as hardware address", "Correct normalized MAC"}, {"BOM-ADDRESS-DUPLICATE", "field", "Unique applicable address", "Reconcile conflicting ownership"}, {"BOM-NETWORK-RANGE", "network", "Numeric MTU/VLAN/VNI/ASN scope", "Correct invalid value"}, {"BOM-SECRET", "security", "Only controlled credential references allowed", "Exclude credential values"}, {"BOM-CABLE-SELF", "connection", "Distinct cable endpoints", "Select two distinct physical ports"}, {"BOM-SPEED", "connection", "Explicit speed consistency", "Map compatible endpoint rates"}, {"BOM-RACK", "rack", "Known rack identity", "Map rack reference"}, {"BOM-BASELINE", "network", "Approved baseline reference", "Bind approved baseline revision"}, {"CROSS-SHEET-CONFLICT", "material", "Same stable identity has consistent values", "Review original sources and correct conflict"}, {"STATE", "import", "Available authoritative import state", "Retry after service recovery"}, {"BOM-NONEMPTY", "import", "At least one confirmed entity", "Map source records"}, {"BOM-CATEGORY", "material", "Explicit supported material category", "Classify candidate"}} {
		rules = append(rules, RuleDefinition{r.ID, "1.0", r.Scope, "BLOCKER", r.Basis, r.Remedy})
	}
	rules = append(rules, RuleDefinition{"SENSITIVE-EXCLUDED", "1.0", "source-document", "INFO", "Sensitive cells are excluded from candidates and AI", "Keep original document restricted; use controlled credential references"})
	rules = append(rules, RuleDefinition{"FORMULA-CACHE", "1.0", "source-field", "WARNING", "Formula cache is not newly calculated evidence", "Confirm current applicability with source and revision"})
	return rules
}
